mapper.select:
SELECT 'COMPONENT' target_type, c.id target_id FROM knowledge_component c JOIN knowledge_page p ON p.id=c.page_id WHERE p.system_code=#{systemCode} AND p.project_code=#{projectCode} AND p.page_path=#{pagePath} AND c.component_id=#{componentId}
UNION SELECT 'PAGE', p.id FROM knowledge_page p WHERE p.system_code=#{systemCode} AND p.project_code=#{projectCode} AND p.page_path=#{pagePath}
UNION SELECT 'FLOW', f.id FROM knowledge_page p JOIN knowledge_page_flow pf ON pf.page_id=p.id JOIN knowledge_flow f ON f.id=pf.flow_id AND f.system_code=p.system_code AND f.project_code=p.project_code WHERE p.system_code=#{systemCode} AND p.project_code=#{projectCode} AND p.page_path=#{pagePath} ORDER BY target_type, target_id

mapper.delete:
DELETE r FROM knowledge_component_relation r
LEFT JOIN knowledge_component_interaction i ON i.id=r.interaction_id
WHERE r.target_component_id=#{componentId} OR i.component_id=#{componentId}

DELETE e FROM knowledge_entry e
JOIN knowledge_applicability a ON a.knowledge_id=e.id AND a.target_type='COMPONENT' AND a.target_id=#{componentId}
LEFT JOIN knowledge_applicability other ON (other.knowledge_id=e.id OR other.replaces_knowledge_id=e.id)
  AND (other.target_type<>'COMPONENT' OR other.target_id<>#{componentId})
WHERE other.id IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM knowledge_component_version cv
    WHERE cv.component_id<>#{componentId}
      AND JSON_SEARCH(cv.manifest, 'one', e.id, NULL, '$[*].objectId') IS NOT NULL
  )
